cambios.texto_viejo:
for campo in campos:
    if "NO_ENCONTRADO" in str(propuesta.get(campo) or ""):
        return True
return False

cambios.texto_nuevo:
marca = "NO" + "_" + "ENCONTRADO"
for campo in campos:
    valor = str(propuesta.get(campo) or "")
    if campo == "archivo":
        if marca in valor:
            return True
        continue
    limpio = valor.strip()
    if limpio == marca:
        return True
    if limpio.startswith(marca):
        return True
    if len(valor.splitlines()) <= 3 and marca in valor:
        return True
return False
